import{_ as s,o as t,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Présences et absences","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/vie-scolaire/presences-et-absences.md","filePath":"src/guide/vie-scolaire/presences-et-absences.md"}'),r={name:"guide/vie-scolaire/presences-et-absences.md"};function i(o,e,l,u,c,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="presences-et-absences" tabindex="-1">Présences et absences <a class="header-anchor" href="#presences-et-absences" aria-label="Permalink to &quot;Présences et absences&quot;">​</a></h1><p>Cette page couvre l&#39;appel quotidien des classes et le traitement des justificatifs d&#39;absence ou de retard soumis par les familles depuis leur espace parent.</p><h2 id="faire-l-appel-quotidien" tabindex="-1">Faire l&#39;appel quotidien <a class="header-anchor" href="#faire-l-appel-quotidien" aria-label="Permalink to &quot;Faire l&#39;appel quotidien&quot;">​</a></h2><ol><li>Ouvrez <strong>Vie scolaire → Présences</strong>. La liste affiche toutes vos classes, avec un badge <strong>Appel du jour</strong> indiquant combien d&#39;élèves ont déjà été pointés sur le total inscrit (par exemple « 18/24 fait »).</li><li>Cliquez sur <strong>Faire l&#39;appel</strong> sur la ligne de la classe concernée.</li><li>Par défaut, la page affiche le jour en cours ; changez la date en haut de page si vous devez compléter ou corriger l&#39;appel d&#39;un jour passé. L&#39;appel d&#39;un jour à venir n&#39;est pas possible.</li><li>Tous les élèves sont <strong>Présent</strong> par défaut : il suffit d&#39;un clic sur <strong>Absent</strong> ou <strong>Retard</strong> pour ceux qui ne le sont pas. Les compteurs à côté de la date se mettent à jour au fur et à mesure, et <strong>Tous présents</strong> remet toute la classe à <strong>Présent</strong>. <ul><li>Pour un élève en <strong>Retard</strong>, indiquez le nombre de minutes.</li><li>Pour un élève absent ou en retard, cochez <strong>Justifié</strong> si le motif est déjà connu, et ajoutez une note libre si besoin (par exemple « certificat médical fourni »).</li></ul></li><li>Cliquez sur <strong>Enregistrer l&#39;appel</strong> dans la barre du bas : tout l&#39;appel de la classe est enregistré en une fois. Si vous quittez la page avant, ERA vous demande de confirmer.</li></ol><h2 id="traiter-les-justificatifs-d-absence" tabindex="-1">Traiter les justificatifs d&#39;absence <a class="header-anchor" href="#traiter-les-justificatifs-d-absence" aria-label="Permalink to &quot;Traiter les justificatifs d&#39;absence&quot;">​</a></h2><p>Les familles soumettent leurs justificatifs d&#39;absence ou de retard depuis leur espace parent ; ils apparaissent dans <strong>Vie scolaire → Justifications d&#39;absence</strong> avec le statut <strong>En attente</strong>.</p><ol><li>Ouvrez <strong>Justifications d&#39;absence</strong>. La liste affiche, pour chaque demande, l&#39;élève, sa classe, la date concernée, le motif indiqué et son statut. Cliquez sur une ligne pour ouvrir le détail.</li><li>Si un document a été joint, téléchargez-le via <strong>Télécharger le document</strong> pour le vérifier avant de statuer.</li><li>Sur une demande <strong>en attente</strong>, choisissez : <ul><li><strong>Approuver</strong> — la justification est validée immédiatement, sans saisie supplémentaire ;</li><li><strong>Rejeter</strong> — une boîte de dialogue vous demande de saisir un <strong>Motif du rejet</strong>, obligatoire, avant de confirmer.</li></ul></li></ol><p>Une fois traitée, la demande passe au statut <strong>Approuvée</strong> ou <strong>Rejetée</strong> ; un justificatif rejeté affiche son motif de rejet directement dans la liste.</p><h3 id="ce-qui-se-passe-automatiquement-quand-vous-approuvez" tabindex="-1">Ce qui se passe automatiquement quand vous approuvez <a class="header-anchor" href="#ce-qui-se-passe-automatiquement-quand-vous-approuvez" aria-label="Permalink to &quot;Ce qui se passe automatiquement quand vous approuvez&quot;">​</a></h3><p>Approuver une justification ne se contente pas de changer son statut :</p><ul><li><strong>La feuille d&#39;appel est mise à jour toute seule.</strong> L&#39;absence concernée passe en <strong>Justifié</strong>, et le motif saisi par la famille est recopié dans la note du relevé. Vous n&#39;avez pas à retourner dans <strong>Présences</strong> pour cocher la case à la main — le faire ne servirait à rien.</li><li><strong>La famille est prévenue</strong> de votre décision, qu&#39;elle soit une approbation ou un rejet. Inutile de la rappeler pour l&#39;informer.</li><li><strong>La décision est définitive.</strong> Une demande déjà approuvée ou rejetée ne peut plus être rouverte : l&#39;app refuse de la traiter une seconde fois. En cas d&#39;erreur, corrigez directement le relevé de présence de l&#39;élève dans <strong>Présences</strong>.</li></ul><h3 id="ce-que-vous-voyez-et-ce-que-vous-ne-voyez-pas" tabindex="-1">Ce que vous voyez, et ce que vous ne voyez pas <a class="header-anchor" href="#ce-que-vous-voyez-et-ce-que-vous-ne-voyez-pas" aria-label="Permalink to &quot;Ce que vous voyez, et ce que vous ne voyez pas&quot;">​</a></h3><p>Vous ne pouvez faire l&#39;appel et statuer que sur les <strong>classes auxquelles vous avez accès</strong>. Si la liste des classes est vide, ce n&#39;est pas un dysfonctionnement : aucune classe ne vous est rattachée. C&#39;est l&#39;administration qui gère ces rattachements, via les affectations d&#39;enseignants et les classes elles-mêmes.</p><div class="tip custom-block"><p class="custom-block-title">Les absences alimentent les indicateurs</p><p>Le taux d&#39;absentéisme du <a href="/era-guide/guide/admin/tableau-de-bord.html">tableau de bord</a> se calcule à partir des appels réellement saisis. Un appel non fait ne compte pas comme une absence : il ne compte pas du tout.</p></div>',14)])])}const m=s(r,[["render",i]]);export{g as __pageData,m as default};
